from dsl import *

LESSON = {
    "id": "l12",
    "label": "12",
    "title": "Using may and mayroón",
    "summary": "Saying there is / there are and has / have with may and mayroón, and saying none with walâ",
    "minutes": 30,
    "goals": [
        "Use may before a noun, adjective, number, mga or verb",
        "Use mayroón (or meron) before short words like ka, pa, ba and before pronouns",
        "Turn a may sentence into a mayroón sentence",
        "Answer a may or mayroón question with mayroón or walâ (not hindî)",
        "Use walâ to say there is no, does not have, or none",
    ],
    "sections": [
        S("May and mayroón: there is, has",
          P("Sentences with **may** or **mayroón** (said *may-ro-on*) point to the **existence** of things (*there is* or *there are*) or to **possession** (*has* or *have*)."),
          P("Both words can mean *there is / there are* and *has / have*, but you **cannot swap one for the other freely**. Each has its own rules, shown below. The opposite of both is **walâ**."),
          TABLE(["Word", "Meaning", "What comes right after it"],
                [["[[may|pred]]", "there is / there are; has / have", "a noun, an adjective, a number, mga, or a verb"],
                 ["[[mayroón|pred]]  (short form [[meron|pred]])", "has / have", "a short word (ka, na, nang, pa, ba, din, daw) or a personal pronoun, with a ligature"],
                 ["[[walâ|pred]]", "there is / there are no; do / does not have; none", "a pronoun or short word (with -ng), or -ng and then a noun, adjective, number, mga or verb"]],
                title="The three words at a glance")),

        S("How to use may",
          H("1. May + a noun"),
          P("**May** is followed **immediately by a noun**. It works in both word orders: the subject-predicate order (with ay) and the inverted order. May sentences often do not say who the owner is (see the last sentence)."),
          EXS([("Akó ay may kaibígan sa Quezon City.", "I have a friend in Quezon City.",
                [("Akó", "I", "pron"), ("ay", "(links)", "ay"), ("may", "have", "pred"), ("kaibígan", "friend", "noun"), ("sa", "in", "marker"), ("Quezon City", "Quezon City", "noun")]),
               ("May kaibígan ako sa Quezon City.", "I have a friend in Quezon City.",
                [("May", "have", "pred"), ("kaibígan", "friend", "noun"), ("ako", "I", "pron"), ("sa", "in", "marker"), ("Quezon City", "Quezon City", "noun")]),
               ("Kami ay may báhay sa Maynilà.", "We have a house in Manila.",
                [("Kami", "we", "pron"), ("ay", "(links)", "ay"), ("may", "have", "pred"), ("báhay", "house", "noun"), ("sa", "in", "marker"), ("Maynilà", "Manila", "noun")]),
               ("May báhay kami sa Maynilà.", "We have a house in Manila.",
                [("May", "have", "pred"), ("báhay", "house", "noun"), ("kami", "we", "pron"), ("sa", "in", "marker"), ("Maynilà", "Manila", "noun")]),
               ("May táo sa labás.", "There is someone outside.",
                [("May", "there is", "pred"), ("táo", "person", "noun"), ("sa", "at", "marker"), ("labás", "outside", "noun")])],
              title="May + noun"),
          PAT("May goes straight before the noun",
              [("Subject first", [("Akó", "pron"), ("ay", "ay"), ("may", "pred"), ("kaibígan", "noun")]),
               ("Inverted", [("May", "pred"), ("kaibígan", "noun"), ("ako", "pron")])],
              note="I have a friend. Nothing comes between may and the noun."),
          H("2. May + an adjective or a number"),
          P("**May** can also be followed **immediately by an adjective or a number**, in either word order, to show possession or existence."),
          EXS([("Siya'y may magandáng báhay.", "He/She has a nice house.",
                [("Siya'y", "he/she (+ ay)", "pron"), ("may", "has", "pred"), ("magandáng", "nice (+ ligature)", "pred"), ("báhay", "house", "noun")]),
               ("May dálawang áso sa kúlúngan.", "There are two dogs in the cage.",
                [("May", "there are", "pred"), ("dálawang", "two (+ ligature)", "noun"), ("áso", "dog", "noun"), ("sa", "in", "marker"), ("kúlúngan", "cage", "noun")])]),
          BOX("tip", "Siya'y", t="**Siya'y** is **siyá + ay** run together, the same shortening of ay you met in earlier lessons."),
          H("3. May + mga + a noun"),
          P("When there is **more than one thing**, may is followed immediately by **mga** and then the noun."),
          EXS([("May mga púnong-kahoy silá.", "They have trees.",
                [("May", "have", "pred"), ("mga", "(plural)", "marker"), ("púnong-kahoy", "trees", "noun"), ("silá", "they", "pron")]),
               ("May mga tao sa labás.", "There are men outside.",
                [("May", "there are", "pred"), ("mga", "(plural)", "marker"), ("tao", "people", "noun"), ("sa", "at", "marker"), ("labás", "outside", "noun")])]),
          H("4. May + a verb"),
          P("May can be followed immediately by a **verb** to show that **someone or something exists** doing that action."),
          EXS([("May natutúlog na táo sa silíd.", "There is a person sleeping in the room.",
                [("May", "there is", "pred"), ("natutúlog", "sleeping", "pred"), ("na", "(ligature)", "link"), ("táo", "person", "noun"), ("sa", "in", "marker"), ("silíd", "room", "noun")])]),
          BOX("remember", "May in short", items=[
              "May + noun: May táo sa labás.",
              "May + adjective or number: may magandáng báhay, may dálawang áso.",
              "May + mga + noun: May mga tao sa labás.",
              "May + verb: May natutúlog na táo sa silíd."]),
          VOC("may", "Words for this lesson")),

        S("How to use mayroón",
          H("1. Mayroón + a short word"),
          P("**Mayroón** is followed by **one-syllable words** such as **ka, na, nang, pa, ba, din** and **daw** (Lesson Ten covers these words). The ligature is then attached to the short word that sits **nearest to the noun or adjective**. Mayroón may be shortened to **meron**."),
          EXS([("Mayroón pang trabáho si Lucio.", "Lucio still has a job.",
                [("Mayroón", "has", "pred"), ("pang", "still (pa + ligature)", "part"), ("trabáho", "job", "noun"), ("si", "(name marker)", "marker"), ("Lucio", "Lucio", "noun")]),
               ("Meron ka bang bágong aklát?", "Do you have a new book?",
                [("Meron", "have", "pred"), ("ka", "you", "pron"), ("bang", "(question word + ligature)", "part"), ("bágong", "new (+ ligature)", "pred"), ("aklát", "book", "noun")])]),
          BOX("tip", "Where does the -ng go?", t="In *Meron ka bang bágong aklát?* there are two short words, **ka** and **ba**. The ligature goes on **ba** (bang), because ba is the one nearest to the noun phrase."),
          H("2. Mayroón + a personal pronoun"),
          P("In inverted sentences, mayroón is followed by a **personal pronoun** such as **akó, ka, tayó, kamí, kayó** and **silá** to show possession. These pronouns end in vowels, so the ligature **-ng** is added to them (kamí + ng = **kamíng**)."),
          P("To change a **may** sentence into a **mayroón** sentence, rearrange **may + noun + pronoun** into **mayroón + pronoun + -ng + noun**."),
          PAT("From may to mayroón",
              [("May", [("May", "pred"), ("báhay", "noun"), ("kamí", "pron"), ("sa Maynilà", "other")]),
               ("Mayroón", [("Mayroón", "pred"), ("kamí", "pron"), ("-ng", "link"), ("báhay", "noun"), ("sa Maynilà", "other")])],
              note="We have a house in Manila."),
          EXS([("May báhay kamí sa Maynilà.", "We have a house in Manila.",
                [("May", "have", "pred"), ("báhay", "house", "noun"), ("kamí", "we", "pron"), ("sa", "in", "marker"), ("Maynilà", "Manila", "noun")]),
               ("Mayroón kamíng báhay sa Maynilà.", "We have a house in Manila.",
                [("Mayroón", "have", "pred"), ("kamíng", "we (+ ligature)", "pron"), ("báhay", "house", "noun"), ("sa", "in", "marker"), ("Maynilà", "Manila", "noun")])]),
          H("3. Mayroón as an answer"),
          P("**Mayroón** on its own answers a question. The word **oo** (*yes*) at the start, and the noun or pronoun after mayroón, are both **optional**."),
          EXS([("May bágong sapátos ba si Bob? (Oo), mayroón (siyá).", "Does Bob have a new pair of shoes? (Yes), he has.",
                [("May", "has", "pred"), ("bágong", "new (+ ligature)", "pred"), ("sapátos", "shoes", "noun"), ("ba", "(question word)", "part"), ("si", "(name marker)", "marker"), ("Bob", "Bob", "noun"), ("Oo", "yes", "part"), ("mayroón", "has", "pred"), ("siyá", "he", "pron")])]),
          H("The ma- prefix is a short may"),
          P("The **ma-** prefix that is added to root words to make other words is really a **shortened form of may**:"),
          TABLE(["Word", "Comes from", "Literally"],
                [["[[marámi|pred]] (many)", "may damí", "there are many"],
                 ["[[mataás|pred]] (tall)", "may taás", "there is height"],
                 ["[[malinís|pred]] (clean)", "may linís", "there is clean"],
                 ["[[mabutó|pred]] (bony)", "", "having many bones"]],
                title="Ma- = may"),
          BOX("rule", "Ma- in short", t="With **abstract** nouns (ideas such as height), ma- means **there is / there are**. With **concrete** nouns (things you can touch, such as bones), ma- means **having many**: mabutó, bony.")),

        S("How to use walâ",
          P("To deny that something exists or is owned, **replace may and mayroón with walâ**. Walâ turns *there is / there are* into **there is / there are no**, and *has / have* into **does not / do not have**. On its own, or as an answer to a mayroón question, walâ means **none**."),
          P("Walâ follows three simple rules, based on the may and mayroón rules."),
          H("1. Walâ + a pronoun or short word"),
          P("Walâ usually comes at the **start of the sentence** and is followed by a **possessive pronoun or a one-syllable word**. The ligature **-ng** is added to the pronoun or short word that comes after it."),
          EXS([("Walâ akóng kaibígan sa Quezon.", "I do not have a friend in Quezon.",
                [("Walâ", "do not have", "pred"), ("akóng", "I (+ ligature)", "pron"), ("kaibígan", "friend", "noun"), ("sa", "in", "marker"), ("Quezon", "Quezon", "noun")]),
               ("Walâ siláng mga púnong-kahoy.", "They do not have trees.",
                [("Walâ", "do not have", "pred"), ("siláng", "they (+ ligature)", "pron"), ("mga", "(plural)", "marker"), ("púnong-kahoy", "trees", "noun")]),
               ("Walá pang bágong aklát.", "There is no new book yet.",
                [("Walá", "there is no", "pred"), ("pang", "yet (pa + ligature)", "part"), ("bágong", "new (+ ligature)", "pred"), ("aklát", "book", "noun")]),
               ("Walá nang trabáho si Lucio.", "Lucio does not have a job now (or anymore).",
                [("Walá", "does not have", "pred"), ("nang", "now / anymore", "part"), ("trabáho", "job", "noun"), ("si", "(name marker)", "marker"), ("Lucio", "Lucio", "noun")])]),
          H("2. Walâ + -ng before other words"),
          P("Walâ **with the ligature -ng** (walâng) is used before **numbers or adjectives, nouns, the article mga, and verbs**, just like may."),
          EXS([("Walâng dálawang áso sa kúlúngan.", "There are no two dogs in the cage.",
                [("Walâng", "there are no", "pred"), ("dálawang", "two (+ ligature)", "noun"), ("áso", "dog", "noun"), ("sa", "in", "marker"), ("kúlúngan", "cage", "noun")]),
               ("Walâng táo sa labás.", "There is no one outside.",
                [("Walâng", "there is no", "pred"), ("táo", "person", "noun"), ("sa", "at", "marker"), ("labás", "outside", "noun")]),
               ("Walâng mga táo sa labás.", "There are no men outside.",
                [("Walâng", "there are no", "pred"), ("mga", "(plural)", "marker"), ("táo", "people", "noun"), ("sa", "at", "marker"), ("labás", "outside", "noun")]),
               ("Waláng natutúlog na táo sa silíd.", "No one is sleeping in the room.",
                [("Waláng", "there is no", "pred"), ("natutúlog", "sleeping", "pred"), ("na", "(ligature)", "link"), ("táo", "person", "noun"), ("sa", "in", "marker"), ("silíd", "room", "noun")])]),
          PAT("May and walâ side by side",
              [("There is", [("May", "pred"), ("táo", "noun"), ("sa labás", "other")]),
               ("There is no", [("Walâ", "pred"), ("-ng", "link"), ("táo", "noun"), ("sa labás", "other")])],
              note="May táo sa labás. / Walâng táo sa labás."),
          H("3. Walâ as an answer: none"),
          P("**Walâ** by itself is the negative answer to a question with **may** or **mayroón**, and means **none**. **Hindî** (*no*) is the **wrong** answer to this kind of question. Walâ can also turn a positive question into a negative one."),
          EXS([("May bágong sapátos ba si Bob? Walâ.", "Does Bob have a new pair of shoes? None.",
                [("May", "has", "pred"), ("bágong", "new (+ ligature)", "pred"), ("sapátos", "shoes", "noun"), ("ba", "(question word)", "part"), ("si", "(name marker)", "marker"), ("Bob", "Bob", "noun"), ("Walâ", "none", "pred")]),
               ("May kótse ba silá? Walâ.", "Do they have a car? None.",
                [("May", "have", "pred"), ("kótse", "car", "noun"), ("ba", "(question word)", "part"), ("silá", "they", "pron"), ("Walâ", "none", "pred")]),
               ("Mayroón ka bang pagkáin?", "Do you have food?",
                [("Mayroón", "have", "pred"), ("ka", "you", "pron"), ("bang", "(question word + ligature)", "part"), ("pagkáin", "food", "noun")]),
               ("Walâ ka bang pagkáin?", "Don't you have food?",
                [("Walâ", "do not have", "pred"), ("ka", "you", "pron"), ("bang", "(question word + ligature)", "part"), ("pagkáin", "food", "noun")])]),
          BOX("warn", "Not hindî", t="To answer *May kótse ba silá?* say **Walâ** (none), never *Hindî*."),
          BOX("english", "Spelling in the book", t="The book prints walâ with a circumflex (walâ, walâng) in most places, but **Walá** / **Waláng** in a few sentences. They are the same word; the sentences here are copied as printed."),
          BOX("remember", "Remember", items=[
              "May comes straight before a noun, adjective, number, mga or verb.",
              "Mayroón (meron) comes before short words like ka, pa, ba, or a pronoun; the -ng goes on the word nearest the noun.",
              "May báhay kamí → Mayroón kamíng báhay.",
              "Walâ replaces may and mayroón: walâ akóng…, walâng táo…",
              "Answer a may or mayroón question with mayroón or walâ, never hindî."]),
          VOC("more", "More words from this lesson")),
    ],
    "vocab": [
        V("may", "may", "there is / there are; has / have", pos="verb", group="may"),
        V("mayroon", "mayroón", "has/have", say="may-ro-ON", pos="verb", group="may", note="Pronounced may-ro-on. Followed by short words (ka, pa, ba…) or a pronoun."),
        V("meron", "meron", "has/have (shortened form of mayroón)", pos="verb", group="may"),
        V("wala", "walâ", "none; there is/there are no; do/does not have", say="wa-laQ", pos="verb", group="may", note="The book also writes walá in a few sentences."),
        V("silid", "silíd", "room", say="si-LID", group="may"),
        V("punongkahoy", "púnongkahoy", "trees", group="may", note="The book also writes púnong-kahoy."),
        V("labas-l12", "labás", "outside", say="la-BAS", group="may"),
        V("kulungan", "kúlúngan", "cage", group="may"),
        V("trabaho", "trabáho", "job", say="tra-BA-ho", group="may"),
        V("natutulog", "natutúlog", "sleeping", say="na-tu-TU-log", pos="verb", group="may"),
        V("mabuto", "mabutó", "bony (literally, having many bones)", say="ma-bu-TO", pos="adj", group="may"),
        V("masarap-m12", "másarap", "delicious", say="MA-sa-rap", pos="adj", group="more", note="Lesson 4 prints masaráp"),
        V("dalawang-m12", "dálawang", "two (with the ligature -ng)", say="DA-la-wang", pos="num", group="more", note="From: May dálawang áso sa kúlúngan. = There are two dogs in the cage."),
        V("mataas-m12", "mataás", "tall", say="ma-ta-AS", pos="adj", group="more", note="Lesson 4 lists mataás = high"),
        V("taas-m12", "taás", "height", say="ta-AS", group="more", note="may taás = literally, there is height"),
        V("may-dami-m12", "may damí", "there are many", pos="phrase", group="more", note="marámi (many) is may damí"),
        V("may-taas-m12", "may taás", "there is height (literally)", pos="phrase", group="more", note="mataás (tall) is may taás"),
        V("may-linis-m12", "may linís", "there is clean", pos="phrase", group="more", note="malinís (clean) is may linís"),
        V("ma-prefix-m12", "ma-", "there is/are (with abstract nouns); having many (with concrete nouns)", pos="other", group="more", note="A contracted form of may"),
        V("sa-aklatan-m12", "sa aklatan", "in the library", pos="phrase", group="more"),
    ],
    "exercises": [
        CH("Which word means \"there is / there are\" and \"has / have\" and goes straight before a noun?", ["may", "walâ", "hindî"], "may", "May + noun: May táo sa labás."),
        CH("What is the short form of mayroón?", ["meron", "may", "mga"], "meron", "Mayroón may be shortened to meron."),
        CH("Fill in: Ako ay ___ mabaít na anák.", ["may", "mayroón"], "may", "Mabaít is an adjective, so may comes right before it."),
        CH("Fill in: ___ bang aklát si John?", ["Mayroón", "May"], "Mayroón", "Mayroón is followed by a short word like ba (bang)."),
        CH("Fill in: ___ pera ba kayó?", ["May", "Mayroón"], "May", "Pera is a noun, so may comes right before it."),
        CH("Fill in: ___ kamíng masayáng búhay.", ["Mayroón", "May"], "Mayroón", "Mayroón is followed by a pronoun with -ng (kamíng)."),
        CH("Fill in: ___ kumakáing batà sa silíd.", ["May", "Mayroón"], "May", "May can be followed straight by a verb."),
        CH("Turn into a mayroón sentence: May báhay kamí sa Maynilà.", ["Mayroón kamíng báhay sa Maynilà.", "Mayroón báhay kamí sa Maynilà.", "Mayroón kamí báhay sa Maynilà."], "Mayroón kamíng báhay sa Maynilà.", "Mayroón + pronoun + -ng + noun."),
        CH("In \"Meron ka bang bágong aklát?\", which short word takes the ligature?", ["ba (bang)", "ka (kang)", "meron (merong)"], "ba (bang)", "The ligature goes on the short word nearest to the noun or adjective."),
        CH("May kótse ba silá? How do you answer \"none\"?", ["Walâ.", "Hindî.", "May."], "Walâ.", "Hindî is an incorrect answer to a may or mayroón question."),
        CH("How do you say \"There is no one outside\"?", ["Walâng táo sa labás.", "Hindî táo sa labás.", "Walâ táo sa labás."], "Walâng táo sa labás.", "Walâ takes -ng before a noun."),
        CH("How do you say \"I do not have a friend in Quezon\"?", ["Walâ akóng kaibígan sa Quezon.", "May kaibígan ako sa Quezon City.", "Walâng táo sa labás."], "Walâ akóng kaibígan sa Quezon.", "The -ng goes on the pronoun after walâ."),
        CH("For more than one thing, may is followed by…", ["mga, then the noun", "the noun, then mga", "ng"], "mga, then the noun", "May mga tao sa labás."),
        CH("The ma- in mataás (tall) is a short form of…", ["may", "mga", "mayroón"], "may", "Mataás comes from may taás, literally there is height."),
        CH("With a concrete noun, like bones, ma- means…", ["having many", "there is no", "very"], "having many", "Mabutó: bony, literally having many bones."),
        CH("\"Walâ ka bang pagkáin?\" means…", ["Don't you have food?", "Do you have food?", "There is food."], "Don't you have food?", "Walâ turns a positive question into a negative one."),
        LI("Walâ.", ["None.", "Yes.", "There is."], "None.", "Walâ on its own means none."),
        LI("May táo sa labás.", ["There is someone outside.", "There is no one outside.", "The person is big."], "There is someone outside.", "May + noun shows existence."),
        LI("silíd", ["room", "cage", "job"], "room", "Silíd means room."),
        BU("There is someone outside.", "May táo sa labás."),
        BU("We have a house in Manila.", "Mayroón kamíng báhay sa Maynilà."),
        BU("I have a friend in Quezon City.", "May kaibígan ako sa Quezon City.", tokens=["may", "kaibígan", "ako", "sa", "quezon city"]),
        BU("There are men outside.", "May mga tao sa labás."),
        BU("Do you have food?", "Mayroón ka bang pagkáin?"),
        BU("There is a person sleeping in the room.", "May natutúlog na táo sa silíd."),
        BU("They do not have trees.", "Walâ siláng mga púnong-kahoy."),
        MA("Match the Tagalog to the English.", [("may", "there is / has"), ("walâ", "none"), ("silíd", "room"), ("kúlúngan", "cage"), ("trabáho", "job")]),
        MA("Match each word to what comes right after it.", [("may", "a noun, adjective, number, mga or verb"), ("mayroón", "a short word or a pronoun"), ("walâ (at the start)", "a pronoun or short word + -ng")]),
    ],
    "recap": [
        "May and mayroón show that something exists (there is/are) or is owned (has/have).",
        "May comes straight before a noun, adjective, number, mga or verb.",
        "Mayroón (meron) comes before short words like ka, pa, ba or a pronoun, and the nearest one takes -ng.",
        "Walâ means there is no, does not have, or none: Walâ akóng kaibígan. Walâng táo sa labás.",
        "Answer may and mayroón questions with mayroón or walâ, never hindî.",
        "The ma- prefix is a short may: mataás = may taás.",
    ],
}
